<?php $pageTitle='Destinations'; require 'includes/header.php'; $q=trim($_GET['q']??'');$region=trim($_GET['region']??'');$budget=trim($_GET['budget']??''); $where=["status='active'"];$args=[];if($q!==''){$where[]='(name LIKE ? OR city LIKE ? OR region LIKE ?)';$like="%$q%";$args=array_merge($args,[$like,$like,$like]);}if($region!==''){$where[]='region=?';$args[]=$region;}if($budget==='low')$where[]='estimated_budget < 200000';if($budget==='mid')$where[]='estimated_budget BETWEEN 200000 AND 300000';if($budget==='high')$where[]='estimated_budget > 300000';$st=db()->prepare('SELECT * FROM destinations WHERE '.implode(' AND ',$where).' ORDER BY popularity DESC,name');$st->execute($args);$items=$st->fetchAll();$regions=db()->query("SELECT DISTINCT region FROM destinations WHERE status='active' ORDER BY region")->fetchAll(); ?>
<section class="detail-hero"><div class="container"><p class="section-kicker text-warning">Plan your escape</p><h1>Destinations</h1><p class="lead mb-0">From ancient cities to quiet shores.</p></div></section><div class="container py-5"><form class="card card-body mb-4" method="get"><div class="row g-2"><div class="col-md-5"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Destination, city or region"></div><div class="col-md-3"><select class="form-select" name="region"><option value="">All regions</option><?php foreach($regions as $r): ?><option <?=$region===$r['region']?'selected':''?>><?=e($r['region'])?></option><?php endforeach;?></select></div><div class="col-md-2"><select class="form-select" name="budget"><option value="">Any budget</option><option value="low" <?=$budget==='low'?'selected':''?>>Under 200k</option><option value="mid" <?=$budget==='mid'?'selected':''?>>200k–300k</option><option value="high" <?=$budget==='high'?'selected':''?>>Above 300k</option></select></div><div class="col-md-2 d-grid"><button class="btn btn-primary">Filter</button></div></div></form><p class="text-muted"><?=count($items)?> destinations found</p><div class="row g-4"><?php foreach($items as $d): ?><div class="col-md-6 col-lg-4"><div class="card min-vh-card"><?php if($d['image']):?><img src="<?=url($d['image'])?>" class="card-img-top" alt=""><?php else:?><div class="placeholder-image"><i class="bi bi-geo-alt"></i></div><?php endif;?><div class="card-body d-flex flex-column"><small><?=e($d['city'])?> · <?=e($d['region'])?></small><h4><?=e($d['name'])?></h4><p class="text-muted"><?=e(mb_strimwidth($d['description'],0,130,'…'))?></p><p class="fw-semibold">Estimated from <?=money($d['estimated_budget'])?></p><a href="<?=url('destination-details.php?id='.$d['destination_id'])?>" class="btn btn-primary mt-auto">Explore</a></div></div></div><?php endforeach; if(!$items):?><div class="col"><div class="alert alert-info">No destinations match those filters.</div></div><?php endif;?></div></div><?php require 'includes/footer.php'; ?>
